-- Template-key masking macros for SereneDB (generated from mask_ga.py). RE2 syntax, applied in order.
-- r6d_mask_g10: generic, dataset-agnostic (11 steps). r6d_mask_v10: g10 + 8 BGL/OpenStack keyword rules.

CREATE OR REPLACE MACRO r6d_mask_g10(s) AS
  regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(s, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', '<*>', 'g'), '\d+\.\d+\.\d+\.\d+(:\d+)?', '<*>', 'g'), '\b([0-9A-Fa-f]{2}:){2,}[0-9A-Fa-f]{2}\b', '<*>', 'g'), '\b[\w-]+(\.[\w-]+)+\.(com|net|org|edu|us|local|io)\b', '<*>', 'g'), '(/[^\s/:,()\[\]\"'']+)+/?', '<*>', 'g'), '[^\s(),=:\[\].\"'']*\d[^\s(),=:\[\].\"'']*', '<*>', 'g'), '<\*>([.,:]<\*>)+', '<*>', 'g'), '(?i)\b(true|false|null|root|admin)\b', '<*>', 'g'), '\.*(<\*>)+', '<*>', 'g'), '<\*>([.,:]<\*>)+', '<*>', 'g'), '<\*>( <\*>)+', '<*>', 'g');

CREATE OR REPLACE MACRO r6d_mask_v10(s) AS
  regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(s, '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}', '<*>', 'g'), '\d+\.\d+\.\d+\.\d+(:\d+)?', '<*>', 'g'), '\b([0-9A-Fa-f]{2}:){2,}[0-9A-Fa-f]{2}\b', '<*>', 'g'), '\b[\w-]+(\.[\w-]+)+\.(com|net|org|edu|us|local|io)\b', '<*>', 'g'), '(/[^\s/:,()\[\]\"'']+)+/?', '<*>', 'g'), '[^\s(),=:\[\].\"'']*\d[^\s(),=:\[\].\"'']*', '<*>', 'g'), '<\*>([.,:]<\*>)+', '<*>', 'g'), '(?i)\b(true|false|null|root|admin)\b', '<*>', 'g'), '\.*(<\*>)+', '<*>', 'g'), '<\*>([.,:]<\*>)+', '<*>', 'g'), '<\*>( <\*>)+', '<*>', 'g'), '(for program |Error loading |from file )[^:]+:', '\1<*>:', 'g'), '(node map file )[^\s:]+', '\1<*>', 'g'), 'chdir\([^)]*\)', 'chdir(<*>)', 'g'), '\b[xyzXYZ][+-](\s|$)', '<*>\1', 'g'), '\b[XYZT] coordinate', '<*> coordinate', 'g'), '\b(EDRAM|directory) error', '<*> error', 'g'), '(status=|ASSERT condition: |for reason |wanted: |machine state register: |monitor caught |Message=).*', '\1<*>', 'g'), '<\*>( <\*>)+', '<*>', 'g');

